async () => {
let out=[],cursor;
for(let i=0;i<20;i++){
const r = await connecta.call("notion_bot.integration_query_data_source",{data_source_id:"ds-roadmap",page_size:100,start_cursor:cursor,filter:{property:"Status",status:{equals:"Blocked"}},properties:["Name","Status"]});
